  kademe: 0,
  zorluk: 1,
  soru: "Bir kamyon kasasına yük çıkarmak için bir tahta eğik biçimde yerleştirilmiştir. Tahtanın zemindeki ucu, kasanın dibinden 24 dm uzaktadır; üst ucu ise yerden 7 dm yüksekteki kasa kenarına dayanmıştır.\n**Tahtanın boyu kaç desimetredir?**",
  gorsel: "<svg viewBox=\"0 0 380 200\" role=\"img\" aria-label=\"Kamyon kasasına dayanan tahta\"><polygon points=\"50,134.3 340,134.3 50,49.7\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><polyline points=\"63,134.3 63,121.3 50,121.3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"195\" y=\"156.3\" font-size=\"15\" text-anchor=\"middle\" fill=\"currentColor\">24 dm</text><text x=\"24.2\" y=\"97\" font-size=\"15\" text-anchor=\"middle\" fill=\"currentColor\">7 dm</text><text x=\"200\" y=\"79.9\" font-size=\"15\" text-anchor=\"middle\" fill=\"currentColor\">?</text></svg>",
  secenekler: ["7","17","24","25"],
